import { execution, actionExecution } from '@dynatrace-sdk/automation-utils';
import { credentialVaultClient, metricsClient } from '@dynatrace-sdk/client-classic-environment-v2';
import { getEnvironmentUrl } from '@dynatrace-sdk/app-environment';

// Task 1 — config
// ══════════════════════════════════════════════════════════════════════════
//  THIS IS THE ONLY TASK YOU NEED TO EDIT.
//
//  1. Store the Entra app's client ID + secret in the Dynatrace credential vault
//     (Settings → Credential vault → Add → "Username and password",
//      username = client ID, password = client secret, scope = App Engine).
//  2. Paste the vault ID and your Entra tenant ID below (graph.*).
//  3. Metric ingest — pick one:
//       a) leave ingest.credentialId empty and grant the workflow actor
//          openpipeline:metrics:ingest, or
//       b) store a Dynatrace API token (scope: metrics.ingest) in the vault as a
//          "Token" credential (scope App Engine) and paste its ID in ingest.credentialId.
//          environmentUrl can stay empty — it defaults to https://<env>.live.dynatrace.com
//  4. Set your departments (or switch to an attribute-based split).
//
//  Secrets are never stored here or returned from this task: every step reads
//  the vault itself using credentialId. This task's result holds IDs only.
// ══════════════════════════════════════════════════════════════════════════
const SETTINGS = {
  "graph": {
    "tenantId": "<entra-tenant-id>",
    "credentialId": "CREDENTIALS_VAULT-XXXXXXXXXXXXXXXX"
  },
  "ingest": {
    "credentialId": "CREDENTIALS_VAULT-XXXXXXXXXXXXXXXX",
    "environmentUrl": ""
  },
  "departmentSource": "managerChain",
  "departments": [
    {
      "name": "Finance",
      "heads": [
        "cfo@company.com"
      ]
    },
    {
      "name": "Marketing",
      "heads": [
        "cmo@company.com"
      ]
    },
    {
      "name": "Operations",
      "heads": [
        "coo@company.com"
      ]
    },
    {
      "name": "People & Culture",
      "heads": [
        "chro@company.com"
      ]
    },
    {
      "name": "Technology",
      "heads": [
        "cio@company.com",
        "cto@company.com"
      ]
    }
  ],
  "orgAttributes": {
    "business_unit": "extensionAttribute3",
    "region": "extensionAttribute4",
    "function": "extensionAttribute2"
  },
  "departmentAttribute": "business_unit",
  "unassignedLabel": "Unassigned",
  "orgHierarchy": true,
  "emitOrgMembership": true,
  "orgMembershipScope": "licensed",
  "agentInventory": true,
  "promptWindowDays": 28,
  "reportPeriod": "D7",
  "metricPrefix": "m365copilot",
  "batchSize": 4,
  "retryBatchSize": 2,
  "pageSize": 500,
  "maxPagesPerUser": 10,
  "timeBudgetMs": 95000
};

export default async function () {
  const problems = [];
  if (!SETTINGS.graph.tenantId || SETTINGS.graph.tenantId.includes('<')) problems.push('graph.tenantId is not set');
  if (!/^CREDENTIALS_VAULT-[A-F0-9]+$/i.test(SETTINGS.graph.credentialId || '')) problems.push('graph.credentialId must look like CREDENTIALS_VAULT-XXXXXXXXXXXXXXXX');
  if (SETTINGS.ingest && SETTINGS.ingest.credentialId && !/^CREDENTIALS_VAULT-[A-F0-9]+$/i.test(SETTINGS.ingest.credentialId)) {
    problems.push('ingest.credentialId must be empty or look like CREDENTIALS_VAULT-XXXXXXXXXXXXXXXX');
  }
  if (SETTINGS.batchSize > 20) problems.push('batchSize must be ≤ 20');
  if (SETTINGS.departmentSource === 'attribute' && !SETTINGS.orgAttributes[SETTINGS.departmentAttribute]) {
    problems.push(`departmentAttribute "${SETTINGS.departmentAttribute}" must be a key of orgAttributes`);
  }
  if (problems.length) throw new Error('Edit the "config" task: ' + problems.join('; '));

  // Prove the credential is readable by this workflow's actor — without returning it.
  let cred;
  try {
    cred = await credentialVaultClient.getCredentialsDetails({ id: SETTINGS.graph.credentialId });
  } catch (e) {
    throw new Error(`Cannot read ${SETTINGS.graph.credentialId}: ${e.message}. Check the credential's scope includes "App Engine" and the workflow actor may read credentials.`);
  }
  if (!cred || !cred.username || !cred.password) {
    throw new Error(`${SETTINGS.graph.credentialId} must be a "Username and password" credential (username = client ID, password = client secret).`);
  }

  // Same check for the optional ingest token.
  if (SETTINGS.ingest && SETTINGS.ingest.credentialId) {
    let t;
    try { t = await credentialVaultClient.getCredentialsDetails({ id: SETTINGS.ingest.credentialId }); }
    catch (e) { throw new Error(`Cannot read ingest credential ${SETTINGS.ingest.credentialId}: ${e.message}. Check its scope includes "App Engine".`); }
    const tok = t && (t.token || t.password);
    if (!tok || !/^dt0c01\./.test(tok)) throw new Error(`${SETTINGS.ingest.credentialId} must be a Token credential holding a Dynatrace API token (dt0c01.…).`);
  }

  console.log(`Ingest: ${SETTINGS.ingest && SETTINGS.ingest.credentialId ? 'API token from vault' : 'workflow actor (needs openpipeline:metrics:ingest)'}`);
  console.log(`Config OK — tenant ${SETTINGS.graph.tenantId}, ${SETTINGS.departments.length} departments (${SETTINGS.departmentSource})`);
  return SETTINGS;
}

import { execution, actionExecution } from '@dynatrace-sdk/automation-utils';
import { credentialVaultClient, metricsClient } from '@dynatrace-sdk/client-classic-environment-v2';
import { getEnvironmentUrl } from '@dynatrace-sdk/app-environment';

// ─────────────────────────────────────────────────────────────────────────────
//  Shared helpers — inlined into every task script by build.mjs.
//  Settings come from the "config" task (edit them there, not here).
// ─────────────────────────────────────────────────────────────────────────────
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const asArray = (x) => (x == null ? [] : Array.isArray(x) ? x : [x]);

let CONFIG = null;
async function loadConfig(ctx) {
  const exe = await execution(ctx.execution_id);
  CONFIG = await exe.result('config');
  if (!CONFIG || !CONFIG.graph) throw new Error('No settings from the "config" task');
  return exe;
}

// fetch with exponential backoff on network errors / 429 / 5xx, honouring Retry-After.
// Returns the final Response (possibly non-OK); throws only if the network never answers.
async function fetchRetry(url, opts = {}, label = url, { retries = 4, deadline = Infinity } = {}) {
  for (let attempt = 1; ; attempt++) {
    let resp, err;
    try { resp = await fetch(url, opts); } catch (e) { err = e; }
    const retryable = err || resp.status === 429 || resp.status >= 500;
    if (!retryable) return resp;
    if (attempt > retries) {
      if (err) throw new Error(`${label}: network error after ${retries} retries: ${err.message}`);
      return resp;
    }
    const ra = resp ? parseInt(resp.headers.get('Retry-After') || '0', 10) : 0;
    const wait = ra > 0 ? ra * 1000 : Math.min(1000 * 2 ** (attempt - 1), 15000);
    if (Date.now() + wait > deadline) { if (err) throw err; return resp; }
    console.log(`${label}: ${err ? 'network error' : resp.status} — retry ${attempt} in ${wait}ms`);
    await sleep(wait);
  }
}

// Client-credentials token for Microsoft Graph. Client ID/secret live in the
// Dynatrace credential vault (type: username/password, scope: AppEngine) —
// never in the script, never returned in task results.
async function graphToken() {
  const cred = await credentialVaultClient.getCredentialsDetails({ id: CONFIG.graph.credentialId });
  const body = new URLSearchParams({
    client_id: cred.username,
    client_secret: cred.password,
    scope: 'https://graph.microsoft.com/.default',
    grant_type: 'client_credentials',
  }).toString();
  const r = await fetchRetry(
    `https://login.microsoftonline.com/${CONFIG.graph.tenantId}/oauth2/v2.0/token`,
    { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body },
    'OAuth'
  );
  if (!r.ok) throw new Error(`OAuth failed (${r.status}): ${await r.text()}`);
  return (await r.json()).access_token;
}

// ── Metric line protocol ──
const metric = (name) => `${CONFIG.metricPrefix}.${name}`;
function dimValue(v) {
  const s = String(v ?? '').replace(/[\r\n]+/g, ' ').slice(0, 240);
  return '"' + s.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
}
function line(name, dims, value) {
  const d = Object.entries(dims || {}).map(([k, v]) => `,${k}=${dimValue(v)}`).join('');
  return `${metric(name)}${d} gauge,${value}`;
}
// Two ingest modes:
//  • ingest.credentialId set → classic Metrics API v2 with a Dynatrace API token read from
//    the credential vault (Token credential, scope "metrics.ingest", vault scope App Engine).
//  • otherwise → platform SDK as the workflow actor (needs openpipeline:metrics:ingest).
async function ingest(lines) {
  const viaToken = !!(CONFIG.ingest && CONFIG.ingest.credentialId);
  const send = viaToken ? await tokenSender() : sdkSender;
  for (let i = 0; i < lines.length; i += 900) {
    const chunk = lines.slice(i, i + 900);
    await send(chunk.join('\n'));
    console.log(`Ingested ${chunk.length} lines (${i + chunk.length}/${lines.length}) via ${viaToken ? 'API token' : 'SDK'}`);
  }
}

async function sdkSender(body) {
  try {
    await metricsClient.ingest({ body });
  } catch (e) {
    if (/403|permission/i.test(String(e && e.message))) {
      throw new Error(`Metric ingest refused for the workflow actor (${e.message}). Either grant the actor ` +
        `"openpipeline:metrics:ingest" (IAM policy: ALLOW openpipeline:metrics:ingest;) or set ingest.credentialId ` +
        `in the config task to a vault Token credential holding an API token with the metrics.ingest scope.`);
    }
    throw e;
  }
}

async function tokenSender() {
  const cred = await credentialVaultClient.getCredentialsDetails({ id: CONFIG.ingest.credentialId });
  const token = cred.token || cred.password;
  if (!token) throw new Error(`${CONFIG.ingest.credentialId} holds no token`);
  const base = (CONFIG.ingest.environmentUrl || getEnvironmentUrl().replace('.apps.', '.live.')).replace(/\/+$/, '');
  return async (body) => {
    const r = await fetchRetry(`${base}/api/v2/metrics/ingest`, {
      method: 'POST',
      headers: { Authorization: `Api-Token ${token}`, 'Content-Type': 'text/plain; charset=utf-8' },
      body,
    }, 'Metric ingest');
    const text = await r.text();
    if (r.status !== 202) throw new Error(`Metric ingest failed (${r.status}) at ${base}: ${text}`);
    const res = text ? JSON.parse(text) : {};
    if (res.linesInvalid) console.log(`WARNING: ${res.linesInvalid} invalid lines: ${JSON.stringify(res.error || {})}`);
  };
}

// ── Copilot appClass → friendly app name (done here so DQL stays simple) ──
const APP_NAMES = {
  outlook: 'Outlook', word: 'Word', excel: 'Excel', powerpoint: 'PowerPoint', onenote: 'OneNote',
  bizchat: 'Copilot Chat (Work)', webchat: 'Copilot Chat (Web)', teams: 'Teams',
  privatechat: 'Teams Private Chat', forms: 'Forms', sharepoint: 'SharePoint', stream: 'Stream',
  loop: 'Loop', m365app: 'M365 App', planner: 'Planner', whiteboard: 'Whiteboard',
  officecopilotsearchanswer: 'Copilot Search', officecopilotnotebook: 'Copilot Notebook',
};
function appName(appClass) {
  const key = String(appClass || 'unknown').toLowerCase().split(/[._]/).pop();
  return APP_NAMES[key] || key.charAt(0).toUpperCase() + key.slice(1);
}

// ── RFC 4180 CSV parser (the Graph report quotes display names containing commas) ──
function parseCsv(text) {
  const rows = []; let row = []; let field = ''; let q = false;
  text = text.replace(/^﻿/, '');
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) {
      if (c === '"') { if (text[i + 1] === '"') { field += '"'; i++; } else q = false; }
      else field += c;
    } else if (c === '"') q = true;
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(field); field = '';
      if (row.some((f) => f !== '')) rows.push(row);
      row = [];
    } else field += c;
  }
  row.push(field);
  if (row.some((f) => f !== '')) rows.push(row);
  const [header = [], ...data] = rows;
  const h = header.map((x) => x.trim());
  return data.map((r) => Object.fromEntries(h.map((k, i) => [k, (r[i] ?? '').trim()])));
}

// ── Loop item: newer runtimes pass it directly, older ones via actionExecution ──
async function loopItem(ctx) {
  if (ctx && ctx.loopItemValue !== undefined) return ctx.loopItemValue;
  if (ctx && ctx.action_execution_id) {
    const ae = await actionExecution(ctx.action_execution_id);
    return ae.loopItem?.item;
  }
  throw new Error('No loop item available');
}

function chunk(arr, size) {
  const out = [];
  for (let i = 0; i < arr.length; i += size) out.push({ idx: out.length, users: arr.slice(i, i + size) });
  return out;
}

// Task 1 — collect
// Pulls the M365 Copilot usage report (licensed users + last activity per app),
// ingests the org-level adoption metrics and the agent inventory, and plans
// the per-user batches for the prompt-counting loop.
export default async function (ctx) {
  await loadConfig(ctx);
  const token = await graphToken();
  const H = { Authorization: `Bearer ${token}` };

  // GA endpoint, CSV stream. Do not add $format or version='v2' (both 400 today).
  const url = `https://graph.microsoft.com/v1.0/copilot/reports/getMicrosoft365CopilotUsageUserDetail(period='${CONFIG.reportPeriod}')`;
  const r = await fetchRetry(url, { headers: H }, 'Usage report');
  if (!r.ok) throw new Error(`Usage report failed (${r.status}): ${await r.text()}`);

  const rows = parseCsv(await r.text()).filter((u) => u['User Principal Name']);
  console.log(`Licensed users in report: ${rows.length}`);

  const concealed = rows.filter((u) => !u['User Principal Name'].includes('@')).length;
  if (concealed > 0) {
    console.log(`WARNING: ${concealed}/${rows.length} UPNs are concealed. Turn off "Display concealed user, group, and site names in all reports" in M365 Admin Center → Settings → Org settings → Reports.`);
  }

  // Every "<App> Copilot Last Activity Date" column → app name. New columns are picked up automatically.
  const appCols = Object.keys(rows[0] || {}).filter((h) => /Last Activity Date$/.test(h) && h !== 'Last Activity Date');
  const appOf = (h) => h.replace(/ Last Activity Date$/, '').replace(/^Microsoft /, '').replace(/ Copilot$/, '');

  const byApp = {};
  let active = 0;
  for (const u of rows) {
    let any = false;
    for (const col of appCols) if (u[col]) { any = true; byApp[appOf(col)] = (byApp[appOf(col)] || 0) + 1; }
    if (any) active++;
  }

  const lines = [
    line('active_users', {}, active),
    line('enabled_users', {}, rows.length),
    line('adoption_pct', {}, rows.length ? Math.round((active / rows.length) * 100) : 0),
    line('report_concealed_upns', {}, concealed),
    ...Object.entries(byApp).map(([app, n]) => line('active_users_by_app', { app }, n)),
  ];

  // ── Agent inventory (beta, optional — failure here never blocks the run) ──
  if (CONFIG.agentInventory) {
    try {
      const ar = await fetchRetry('https://graph.microsoft.com/beta/copilot/admin/catalog/packages', { headers: H }, 'Agent catalog');
      if (ar.ok) {
        const agents = (await ar.json()).value || [];
        const tally = (key) => agents.reduce((m, a) => ((m[a[key] || 'Unknown'] = (m[a[key] || 'Unknown'] || 0) + 1), m), {});
        lines.push(line('agents_total', {}, agents.length));
        lines.push(line('agents_without_owner', {}, agents.filter((a) => !a.owner).length));
        for (const [creator, n] of Object.entries(tally('creatorType'))) lines.push(line('agents_by_creator', { creator }, n));
        for (const [platform, n] of Object.entries(tally('platform'))) lines.push(line('agents_by_platform', { platform }, n));
      } else {
        console.log(`Agent catalog unavailable (${ar.status}) — skipped`);
      }
    } catch (e) {
      console.log(`Agent catalog error — skipped: ${e.message}`);
    }
  }

  await ingest(lines);

  const users = rows.map((u) => ({ upn: u['User Principal Name'], name: u['Display Name'] || u['User Principal Name'] }));
  const batches = chunk(users, CONFIG.batchSize);
  console.log(`Planned ${batches.length} batches of ≤${CONFIG.batchSize}`);

  // Only the work plan goes into the task result — no tokens, no secrets.
  return { totalUsers: users.length, activeUsers: active, concealed, batches };
}

