    const ae = await actionExecution(ctx.action_execution_id);
    return ae.loopItem?.item;
  }
  throw new Error('No loop item available');
}

function chunk(arr, size) {
  const out = [];
  for (let i = 0; i < arr.length; i += size) out.push({ idx: out.length, users: arr.slice(i, i + size) });
  return out;
}

// Task 5 — aggregate
// Merges first pass + retry, pulls the org directory once (all enabled users with
// their manager inline — ~1 Graph call per 999 users), resolves each licensed user's
// department, and ingests per-user, per-app, org and run-health metrics.
export default async function (ctx) {
  const exe = await loadConfig(ctx);
  const plan = await exe.result('collect');
  const read = async (task) => {
    try { return asArray(await exe.result(task)).flatMap((b) => (b && b.users) || []); }
    catch (e) { console.log(`${task}: no results (${e.message})`); return []; }
  };

  const first = await read('count_prompts');
  const retry = await read('retry_prompts');

  const final = new Map(first.map((u) => [u.upn, u]));
  for (const u of retry) {
    const prev = final.get(u.upn);
    if (!prev || u.status !== 'retry' || u.prompts >= prev.prompts) final.set(u.upn, u);
  }
  const users = [...final.values()];
  const expected = plan.batches.reduce((n, b) => n + b.users.length, 0);
  const status = users.reduce((m, u) => ((m[u.status] = (m[u.status] || 0) + 1), m), {});

  // ── Org directory ──
  let org = null;
  if (CONFIG.orgHierarchy) {
    try { org = await loadDirectory(); }
    catch (e) { console.log(`Org directory failed — departments will be "Unknown": ${e.message}`); }
  }

  const lines = [];
  const byApp = {};
  const licensed = new Set(users.map((u) => u.upn.toLowerCase()));
  // Only users with a complete count are written. An errored or incomplete user is
  // left out rather than written as 0, which would show them as an unused licence.
  const counted = users.filter((u) => u.status === 'ok');
  for (const u of counted) {
    const person = org && org.byUpn.get(u.upn.toLowerCase());
    lines.push(line('user_prompts', { upn: u.upn, user: u.name, department: resolveDepartment(u, person, org) }, u.prompts));
    for (const [app, n] of Object.entries(u.byApp || {})) byApp[app] = (byApp[app] || 0) + n;
  }
  for (const [app, n] of Object.entries(byApp)) lines.push(line('prompts_by_app', { app }, n));

  if (org && CONFIG.emitOrgMembership) {
    const scope = CONFIG.orgMembershipScope === 'all' ? org.people : org.people.filter((p) => licensed.has(p.upn.toLowerCase()));
    for (const p of scope) {
      const attrs = Object.fromEntries(Object.keys(CONFIG.orgAttributes).map((k) => [k, p.attrs[k]]));
      const mgr = p.managerId && org.byId.get(p.managerId);
      if (mgr) lines.push(line('org_manager', { upn: p.upn, user: p.name, manager: mgr.name, ...attrs }, 1));
      for (const a of ancestors(p, org)) lines.push(line('org_membership', { upn: p.upn, user: p.name, ancestor: a.name, ancestor_upn: a.upn, ...attrs }, 1));
    }
    lines.push(line('org_users', {}, org.people.length));
    lines.push(line('org_cycles_guarded', {}, org.cycles));
  }

  lines.push(line('run_users_expected', {}, expected));
  lines.push(line('run_users_reported', {}, users.length));
  lines.push(line('run_users_missing', {}, expected - users.length));
  for (const s of ['ok', 'retry', 'error']) lines.push(line('run_users_status', { status: s }, status[s] || 0));
  lines.push(line('run_users_capped', {}, users.filter((u) => u.capped).length));

  await ingest(lines);

  // A mostly-failed run is a setup problem (permissions, URL, token), not real data: fail loudly.
  const failed = users.length - counted.length;
  if (users.length && failed / users.length > 0.5) {
    const reasons = users.filter((u) => u.error).reduce((m, u) => ((m[u.error] = (m[u.error] || 0) + 1), m), {});
    const top = Object.entries(reasons).sort((a, b) => b[1] - a[1]).slice(0, 3).map(([r, n]) => `${n}× ${r}`).join('; ');
    throw new Error(`${failed}/${users.length} users could not be counted, so per-user metrics were not written for them. Most common: ${top}`);
  }

  const active = users.filter((u) => u.prompts > 0).length;
  const summary = {
    expected, reported: users.length, status,
    active, activationPct: users.length ? Math.round((active / users.length) * 100) : 0,
    counted: counted.length,
    totalPrompts: counted.reduce((n, u) => n + u.prompts, 0),
    retried: retry.length, orgUsers: org ? org.people.length : 0, linesIngested: lines.length,
  };
  console.log(JSON.stringify(summary));
  return summary;
}

// All enabled users with manager inline. $expand + simple accountEnabled filter is
// supported together; extension-attribute filters are not, so attributes are read in code.
async function loadDirectory() {
  const H = { Authorization: `Bearer ${await graphToken()}`, ConsistencyLevel: 'eventual' };
  let url = 'https://graph.microsoft.com/v1.0/users' +
    '?$select=id,userPrincipalName,displayName,onPremisesExtensionAttributes' +
    '&$expand=manager($select=id,displayName,userPrincipalName)' +
    '&$filter=accountEnabled eq true&$top=999&$count=true';
  const people = [];
  while (url) {
    const r = await fetchRetry(url, { headers: H }, 'Graph /users', { retries: 5 });
    if (!r.ok) throw new Error(`/users ${r.status}: ${await r.text()}`);
    const page = await r.json();
    for (const u of page.value || []) {
      if (!u.userPrincipalName) continue;
      const ext = u.onPremisesExtensionAttributes || {};
      people.push({
        id: u.id, upn: u.userPrincipalName,
        name: u.displayName || u.userPrincipalName.split('@')[0],
        managerId: u.manager ? u.manager.id : null,
        attrs: Object.fromEntries(Object.entries(CONFIG.orgAttributes).map(([dim, f]) => [dim, ext[f] || 'Unknown'])),
      });
    }
    url = page['@odata.nextLink'] || null;
  }
  const org = { people, byId: new Map(people.map((p) => [p.id, p])), byUpn: new Map(people.map((p) => [p.upn.toLowerCase(), p])), cycles: 0 };
  console.log(`Org directory: ${people.length} enabled users, ${people.filter((p) => p.managerId).length} with a manager`);
  return org;
}

// Manager chain, nearest first. Cycle- and depth-guarded.
function ancestors(p, org) {
  const out = []; const seen = new Set([p.id]);
  let cur = p.managerId;
  while (cur && out.length < 25) {
    if (seen.has(cur)) { org.cycles++; break; }
    seen.add(cur);
    const a = org.byId.get(cur);
    if (!a) break; // manager outside the enabled set
    out.push(a);
    cur = a.managerId;
  }
  return out;
}

// departmentSource "attribute": department = configured org attribute (e.g. business_unit).
// departmentSource "managerChain" (default): walk self → manager → … and take the first
// configured department whose head matches by UPN or display name (nearest wins).
function resolveDepartment(u, person, org) {
  if (!CONFIG.orgHierarchy) return CONFIG.unassignedLabel;
  if (!org) return 'Unknown';
  if (!person) return CONFIG.unassignedLabel; // licensed but not in enabled directory
  if (CONFIG.departmentSource === 'attribute') {
    const v = person.attrs[CONFIG.departmentAttribute];
    return v && v !== 'Unknown' ? v : CONFIG.unassignedLabel;
  }
  const heads = CONFIG.departments.map((d) => ({ name: d.name, keys: new Set(d.heads.map((h) => h.toLowerCase())) }));
  for (const node of [person, ...ancestors(person, org)]) {
    for (const d of heads) if (d.keys.has(node.upn.toLowerCase()) || d.keys.has(node.name.toLowerCase())) return d.name;
  }
  return CONFIG.unassignedLabel;
}

import { execution, actionExecution } from '@dynatrace-sdk/automation-utils';
import { credentialVaultClient, metricsClient } from '@dynatrace-sdk/client-classic-environment-v2';
import { getEnvironmentUrl } from '@dynatrace-sdk/app-environment';

// ─────────────────────────────────────────────────────────────────────────────
//  Shared helpers — inlined into every task script by build.mjs.
//  Settings come from the "config" task (edit them there, not here).
// ─────────────────────────────────────────────────────────────────────────────
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const asArray = (x) => (x == null ? [] : Array.isArray(x) ? x : [x]);

let CONFIG = null;
async function loadConfig(ctx) {
  const exe = await execution(ctx.execution_id);
  CONFIG = await exe.result('config');
  if (!CONFIG || !CONFIG.graph) throw new Error('No settings from the "config" task');
  return exe;
}

// fetch with exponential backoff on network errors / 429 / 5xx, honouring Retry-After.
// Returns the final Response (possibly non-OK); throws only if the network never answers.
async function fetchRetry(url, opts = {}, label = url, { retries = 4, deadline = Infinity } = {}) {
  for (let attempt = 1; ; attempt++) {
    let resp, err;
    try { resp = await fetch(url, opts); } catch (e) { err = e; }
    const retryable = err || resp.status === 429 || resp.status >= 500;
    if (!retryable) return resp;
    if (attempt > retries) {
      if (err) throw new Error(`${label}: network error after ${retries} retries: ${err.message}`);
      return resp;
    }
    const ra = resp ? parseInt(resp.headers.get('Retry-After') || '0', 10) : 0;
    const wait = ra > 0 ? ra * 1000 : Math.min(1000 * 2 ** (attempt - 1), 15000);
    if (Date.now() + wait > deadline) { if (err) throw err; return resp; }
    console.log(`${label}: ${err ? 'network error' : resp.status} — retry ${attempt} in ${wait}ms`);
    await sleep(wait);
  }
}

// Client-credentials token for Microsoft Graph. Client ID/secret live in the
// Dynatrace credential vault (type: username/password, scope: AppEngine) —
// never in the script, never returned in task results.
async function graphToken() {
  const cred = await credentialVaultClient.getCredentialsDetails({ id: CONFIG.graph.credentialId });
  const body = new URLSearchParams({
    client_id: cred.username,
    client_secret: cred.password,
    scope: 'https://graph.microsoft.com/.default',
    grant_type: 'client_credentials',
  }).toString();
  const r = await fetchRetry(
    `https://login.microsoftonline.com/${CONFIG.graph.tenantId}/oauth2/v2.0/token`,
    { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body },
    'OAuth'
  );
  if (!r.ok) throw new Error(`OAuth failed (${r.status}): ${await r.text()}`);
  return (await r.json()).access_token;
}

// ── Metric line protocol ──
const metric = (name) => `${CONFIG.metricPrefix}.${name}`;
function dimValue(v) {
  const s = String(v ?? '').replace(/[\r\n]+/g, ' ').slice(0, 240);
  return '"' + s.replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
}
function line(name, dims, value) {
  const d = Object.entries(dims || {}).map(([k, v]) => `,${k}=${dimValue(v)}`).join('');
  return `${metric(name)}${d} gauge,${value}`;
}
// Two ingest modes:
//  • ingest.credentialId set → classic Metrics API v2 with a Dynatrace API token read from
//    the credential vault (Token credential, scope "metrics.ingest", vault scope App Engine).
//  • otherwise → platform SDK as the workflow actor (needs openpipeline:metrics:ingest).
async function ingest(lines) {
  const viaToken = !!(CONFIG.ingest && CONFIG.ingest.credentialId);
  const send = viaToken ? await tokenSender() : sdkSender;
  for (let i = 0; i < lines.length; i += 900) {
    const chunk = lines.slice(i, i + 900);
    await send(chunk.join('\n'));
    console.log(`Ingested ${chunk.length} lines (${i + chunk.length}/${lines.length}) via ${viaToken ? 'API token' : 'SDK'}`);
  }
}

async function sdkSender(body) {
  try {
    await metricsClient.ingest({ body });
  } catch (e) {
    if (/403|permission/i.test(String(e && e.message))) {
      throw new Error(`Metric ingest refused for the workflow actor (${e.message}). Either grant the actor ` +
        `"openpipeline:metrics:ingest" (IAM policy: ALLOW openpipeline:metrics:ingest;) or set ingest.credentialId ` +
        `in the config task to a vault Token credential holding an API token with the metrics.ingest scope.`);
    }
    throw e;
  }
}

async function tokenSender() {
  const cred = await credentialVaultClient.getCredentialsDetails({ id: CONFIG.ingest.credentialId });
  const token = cred.token || cred.password;
  if (!token) throw new Error(`${CONFIG.ingest.credentialId} holds no token`);
  const base = (CONFIG.ingest.environmentUrl || getEnvironmentUrl().replace('.apps.', '.live.')).replace(/\/+$/, '');
  return async (body) => {
    const r = await fetchRetry(`${base}/api/v2/metrics/ingest`, {
      method: 'POST',
      headers: { Authorization: `Api-Token ${token}`, 'Content-Type': 'text/plain; charset=utf-8' },
      body,
    }, 'Metric ingest');
    const text = await r.text();
    if (r.status !== 202) throw new Error(`Metric ingest failed (${r.status}) at ${base}: ${text}`);
    const res = text ? JSON.parse(text) : {};
    if (res.linesInvalid) console.log(`WARNING: ${res.linesInvalid} invalid lines: ${JSON.stringify(res.error || {})}`);
  };
}

// ── Copilot appClass → friendly app name (done here so DQL stays simple) ──
const APP_NAMES = {
  outlook: 'Outlook', word: 'Word', excel: 'Excel', powerpoint: 'PowerPoint', onenote: 'OneNote',
  bizchat: 'Copilot Chat (Work)', webchat: 'Copilot Chat (Web)', teams: 'Teams',
  privatechat: 'Teams Private Chat', forms: 'Forms', sharepoint: 'SharePoint', stream: 'Stream',
  loop: 'Loop', m365app: 'M365 App', planner: 'Planner', whiteboard: 'Whiteboard',
  officecopilotsearchanswer: 'Copilot Search', officecopilotnotebook: 'Copilot Notebook',
};
function appName(appClass) {
  const key = String(appClass || 'unknown').toLowerCase().split(/[._]/).pop();
  return APP_NAMES[key] || key.charAt(0).toUpperCase() + key.slice(1);
}

// ── RFC 4180 CSV parser (the Graph report quotes display names containing commas) ──
function parseCsv(text) {
  const rows = []; let row = []; let field = ''; let q = false;
  text = text.replace(/^﻿/, '');
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (q) {
      if (c === '"') { if (text[i + 1] === '"') { field += '"'; i++; } else q = false; }
      else field += c;
    } else if (c === '"') q = true;
    else if (c === ',') { row.push(field); field = ''; }
    else if (c === '\n' || c === '\r') {
      if (c === '\r' && text[i + 1] === '\n') i++;
      row.push(field); field = '';
      if (row.some((f) => f !== '')) rows.push(row);
      row = [];
    } else field += c;
  }
  row.push(field);
  if (row.some((f) => f !== '')) rows.push(row);
  const [header = [], ...data] = rows;
  const h = header.map((x) => x.trim());
  return data.map((r) => Object.fromEntries(h.map((k, i) => [k, (r[i] ?? '').trim()])));
}

// ── Loop item: newer runtimes pass it directly, older ones via actionExecution ──
async function loopItem(ctx) {
  if (ctx && ctx.loopItemValue !== undefined) return ctx.loopItemValue;
  if (ctx && ctx.action_execution_id) {
    const ae = await actionExecution(ctx.action_execution_id);
    return ae.loopItem?.item;
  }
  throw new Error('No loop item available');
}

function chunk(arr, size) {
  const out = [];
  for (let i = 0; i < arr.length; i += size) out.push({ idx: out.length, users: arr.slice(i, i + size) });
  return out;
}

// Task 3 — plan_retry
// Finds users that are missing (a batch died) or came back as 'retry',
// and re-batches them smaller for a second pass.
export default async function (ctx) {
  const exe = await loadConfig(ctx);
  const plan = await exe.result('collect');
  const expected = plan.batches.flatMap((b) => b.users);

  const seen = new Map();
  try {
    for (const b of asArray(await exe.result('count_prompts'))) for (const u of (b && b.users) || []) seen.set(u.upn, u);
  } catch (e) {
    console.log(`count_prompts results unavailable: ${e.message}`);
  }

  const todo = expected.filter((u) => !seen.has(u.upn) || seen.get(u.upn).status === 'retry');
  console.log(`Expected ${expected.length}, returned ${seen.size}, to retry ${todo.length}`);
  todo.slice(0, 50).forEach((u) => console.log(`  retry: ${u.upn}`));

  return { retryCount: todo.length, retryBatches: chunk(todo, CONFIG.retryBatchSize) };
}

