// Dynatrace Workflow – "Run JavaScript" action
// Copilot Studio credits pull: daily per-agent Copilot Credit consumption from the
// Power Platform licensing API, ingested as bizevents (event.type = copilotstudio.credits.daily).
//
// Entra app (same app as the Copilot licence pull is fine):
//   Register it as a Power Platform management app, or the licensing API returns 403:
//     pac admin application register --application-id <client-id>
// External requests allowlist (Settings > General > External requests):
//   login.microsoftonline.com, api.powerplatform.com, and your own *.live.dynatrace.com host
// Bizevents are ingested with an API token held in the credential vault, so the workflow's
// own identity doesn't need ingest permissions. Token scope: bizevents.ingest
// (if you reuse the metrics.ingest token, add bizevents.ingest to it).
//
// Schedule daily, ~10:00 UTC. Each run re-pulls LOOKBACK_DAYS because Microsoft restates
// recent days; the dashboard de-duplicates on (usage_date, agent, feature, channel, tool, model).

import { credentialVaultClient } from '@dynatrace-sdk/client-classic-environment-v2';
import { getEnvironmentUrl } from '@dynatrace-sdk/app-environment';

// ---------- config ----------
const TENANT_ID = '<entra-tenant-id>';
const CREDENTIAL_ID = 'CREDENTIALS_VAULT-XXXXXXXXXXXXXXXX';        // user/password type: username = clientId, password = secret
const DT_TOKEN_CREDENTIAL_ID = 'CREDENTIALS_VAULT-XXXXXXXXXXXXXXXX'; // token type: Dynatrace API token with bizevents.ingest
const DT_ENV_URL = '';           // optional override, e.g. 'https://abc12345.live.dynatrace.com'; blank = derive from this environment
const LOOKBACK_DAYS = 3;
const DRY_RUN = false;           // true = return what would be ingested, ingest nothing
// -----------------------------

const PP = 'https://api.powerplatform.com';
const API_VERSION = '2024-10-01';

function ingestBaseUrl() {
  if (DT_ENV_URL) return DT_ENV_URL.replace(/\/$/, '');
  return getEnvironmentUrl().replace(/\/$/, '').replace('.apps.dynatrace.com', '.live.dynatrace.com');
}

async function ingestBizevents(events) {
  const cred = await credentialVaultClient.getCredentialsDetails({ id: DT_TOKEN_CREDENTIAL_ID });
  const url = `${ingestBaseUrl()}/api/v2/bizevents/ingest`;
  let sent = 0;
  for (let i = 0; i < events.length; i += 500) {
    const batch = events.slice(i, i + 500);
    const res = await fetch(url, {
      method: 'POST',
      headers: { Authorization: `Api-Token ${cred.token}`, 'Content-Type': 'application/cloudevent-batch+json' },
      body: JSON.stringify(batch),
    });
    if (!res.ok) throw new Error(`Bizevent ingest ${res.status} on ${url}: ${await res.text()}`);
    sent += batch.length;
  }
  return { sent };
}

async function getToken() {
  const cred = await credentialVaultClient.getCredentialsDetails({ id: CREDENTIAL_ID });
  const body = new URLSearchParams({
    client_id: cred.username,
    client_secret: cred.password,
    scope: `${PP}/.default`,
    grant_type: 'client_credentials',
  });
  const res = await fetch(`https://login.microsoftonline.com/${TENANT_ID}/oauth2/v2.0/token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body,
  });
  if (!res.ok) throw new Error(`Token request failed: ${res.status} ${await res.text()}`);
  return (await res.json()).access_token;
}

async function pp(path, token) {
  const url = path.startsWith('http') ? path : `${PP}${path}`;
  const res = await fetch(url, { headers: { Authorization: `Bearer ${token}` } });
  if (!res.ok) throw new Error(`Power Platform ${res.status} on ${url}: ${await res.text()}`);
  return res.json();
}

async function environmentNames(token) {
  const map = {};
  let next = `/environmentmanagement/environments?api-version=${API_VERSION}`;
  while (next) {
    const page = await pp(next, token);
    for (const e of page.value ?? []) map[e.id] = e.displayName ?? e.id;
    next = page['@odata.nextLink'];
  }
  return map;
}

const isoDay = (d) => d.toISOString().slice(0, 10);

export default async function () {
  const token = await getToken();
  const envNames = await environmentNames(token).catch(() => ({})); // display names are nice-to-have

  // Latest complete usage day (fallback: yesterday UTC)
  const tenant = await pp(`/licensing/entitlements/MCSMessages?api-version=${API_VERSION}`, token);
  const lastComplete = tenant?.capacity?.consumed?.lastUpdatedOn
    ? new Date(tenant.capacity.consumed.lastUpdatedOn)
    : new Date(Date.now() - 86400000);

  const ingestTs = new Date().toISOString();
  const events = [];
  const days = [];

  for (let i = 0; i < LOOKBACK_DAYS; i++) {
    const day = isoDay(new Date(lastComplete.getTime() - i * 86400000));
    days.push(day);
    let cont = '';
    do {
      const q =
        `/licensing/entitlements/MCSMessages/resources?fromDate=${day}&toDate=${day}` +
        `&includeFields=users%2Ctags%2CasOfDate&pageSize=5000&api-version=${API_VERSION}` +
        (cont ? `&continuationtoken=${encodeURIComponent(cont)}` : '');
      const page = await pp(q, token);

      // Live response nests value[] -> resources[]; tolerate the flat documented shape too.
      const rows = (page.value ?? []).flatMap((v) => v.resources ?? [v]);
      for (const r of rows) {
        const m = r.metadata ?? {};
        events.push({
          specversion: '1.0',
          source: 'powerplatform.licensing',
          type: 'copilotstudio.credits.daily',
          id: `${day}|${r.resourceId}|${m.FeatureName}|${m.ChannelId}|${m.ToolInvoked}|${m.LLMModel}|${ingestTs}`,
          // Event time = ingest time (Grail rejects/clamps old timestamps); the usage day is in usage_date.
          time: ingestTs,
          data: {
            usage_date: day,
            ingest_ts: ingestTs,
            'environment.id': r.environmentId,
            'environment.name': envNames[r.environmentId] ?? r.environmentId,
            'agent.id': r.resourceId,
            'agent.name': m.ResourceName ?? r.resourceId,
            'credits.billed': Number(r.consumed ?? 0),
            'credits.non_billed': Number(m.NonBillableQuantity ?? 0),
            feature: m.FeatureName ?? 'unknown',
            channel: m.ChannelId ?? 'unknown',
            tool: m.ToolInvoked ?? 'none',
            'llm.model': m.LLMModel ?? 'none',
            'knowledge.sources': m.KnowledgeSources ?? null,
            users: m.Users ?? null,
          },
        });
      }
      cont = page.continuationtoken || page.continuationToken || '';
    } while (cont);
  }

  const ingest = DRY_RUN ? { sent: 0 } : await ingestBizevents(events);

  const byAgent = {};
  for (const e of events) {
    const a = (byAgent[e.data['agent.name']] ??= { billed: 0, nonBilled: 0 });
    a.billed += e.data['credits.billed'];
    a.nonBilled += e.data['credits.non_billed'];
  }

  return {
    dryRun: DRY_RUN,
    lastCompleteDay: isoDay(lastComplete),
    days,
    rows: events.length,
    eventsSent: ingest.sent,
    byAgent,
    sample: events.slice(0, 5).map((e) => e.data),
  };
}

// Dynatrace Workflow – "Run JavaScript" action
// Copilot licence pull: purchased / assigned per SKU + per-user licence assignment
//
// Graph app permissions (application, admin-consented):
//   Organization.Read.All  -> /subscribedSkus
//   User.Read.All          -> /users filtered by assignedLicenses
// External requests allowlist (Settings > General > External requests):
//   login.microsoftonline.com, graph.microsoft.com, and your own *.live.dynatrace.com host
// Metrics are ingested with an API token (scope: metrics.ingest) held in the credential vault,
// so the workflow's own identity doesn't need openpipeline:metrics:ingest.

import { execution } from '@dynatrace-sdk/automation-utils';
import { credentialVaultClient } from '@dynatrace-sdk/client-classic-environment-v2';
import { getEnvironmentUrl } from '@dynatrace-sdk/app-environment';

// ---------- config ----------
// Tenant ID, credential IDs and the ingest URL come from the "config" task (SETTINGS.graph and
// SETTINGS.ingest), so there is nothing tenant-specific to edit here.
const SKU_PATTERN = /COPILOT/i;  // matches Microsoft_365_Copilot etc. (see note on E7 below)
const DRY_RUN = false;           // true = return what would be ingested, ingest nothing
// -----------------------------

let TENANT_ID, CREDENTIAL_ID, DT_TOKEN_CREDENTIAL_ID, DT_ENV_URL;

async function loadConfig(ctx) {
  const exe = await execution(ctx.execution_id);
  const cfg = await exe.result('config');
  if (!cfg || !cfg.graph) throw new Error('No settings from the "config" task');
  TENANT_ID = cfg.graph.tenantId;
  CREDENTIAL_ID = cfg.graph.credentialId;
  DT_TOKEN_CREDENTIAL_ID = cfg.ingest && cfg.ingest.credentialId;
  DT_ENV_URL = (cfg.ingest && cfg.ingest.environmentUrl) || '';
  if (!DT_TOKEN_CREDENTIAL_ID) {
    throw new Error('The licence pull ingests with an API token: set ingest.credentialId in the "config" task to a vault Token credential (scope metrics.ingest).');
  }
}

function ingestBaseUrl() {
  if (DT_ENV_URL) return DT_ENV_URL.replace(/\/$/, '');
  return getEnvironmentUrl().replace(/\/$/, '').replace('.apps.dynatrace.com', '.live.dynatrace.com');
}

async function ingestMetrics(lines) {
  const cred = await credentialVaultClient.getCredentialsDetails({ id: DT_TOKEN_CREDENTIAL_ID });
  const url = `${ingestBaseUrl()}/api/v2/metrics/ingest`;
  let accepted = 0;
  const invalid = [];
  for (let i = 0; i < lines.length; i += 1000) {
    const res = await fetch(url, {
      method: 'POST',
      headers: { Authorization: `Api-Token ${cred.token}`, 'Content-Type': 'text/plain; charset=utf-8' },
      body: lines.slice(i, i + 1000).join('\n'),
    });
    const text = await res.text();
    if (!res.ok && res.status !== 400) throw new Error(`Metric ingest ${res.status} on ${url}: ${text}`);
    const body = text ? JSON.parse(text) : {};
    accepted += body.linesOk ?? 0;
    if (body.linesInvalid) invalid.push({ batch: i / 1000, linesInvalid: body.linesInvalid, error: body.error });
  }
  return { accepted, invalid };
}

const GRAPH = 'https://graph.microsoft.com/v1.0';

async function getToken() {
  const cred = await credentialVaultClient.getCredentialsDetails({ id: CREDENTIAL_ID });
  const body = new URLSearchParams({
    client_id: cred.username,
    client_secret: cred.password,
    scope: 'https://graph.microsoft.com/.default',
    grant_type: 'client_credentials',
  });
  const res = await fetch(`https://login.microsoftonline.com/${TENANT_ID}/oauth2/v2.0/token`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body,
  });
  if (!res.ok) throw new Error(`Token request failed: ${res.status} ${await res.text()}`);
  return (await res.json()).access_token;
}

async function graphGetAll(url, token, extraHeaders = {}) {
  const items = [];
  let next = url;
  while (next) {
    const res = await fetch(next, { headers: { Authorization: `Bearer ${token}`, ...extraHeaders } });
    if (!res.ok) throw new Error(`Graph ${res.status} on ${next}: ${await res.text()}`);
    const data = await res.json();
    items.push(...(data.value ?? []));
    next = data['@odata.nextLink'];
  }
  return items;
}

// Metric line protocol: quote + escape dimension values
const dim = (v) => `"${String(v ?? 'unknown').replace(/\\/g, '\\\\').replace(/"/g, '\\"')}"`;

export default async function (ctx) {
  await loadConfig(ctx);
  const token = await getToken();
  const lines = [];

  // 1. Tenant-level licence counts per Copilot SKU
  const skus = await graphGetAll(`${GRAPH}/subscribedSkus`, token);
  const copilotSkus = skus.filter((s) => SKU_PATTERN.test(s.skuPartNumber) && s.capabilityStatus === 'Enabled');

  for (const s of copilotSkus) {
    const d = `sku=${dim(s.skuPartNumber)}`;
    lines.push(`m365copilot.licences.purchased,${d} ${s.prepaidUnits?.enabled ?? 0}`);
    lines.push(`m365copilot.licences.assigned,${d} ${s.consumedUnits ?? 0}`);
    lines.push(`m365copilot.licences.suspended,${d} ${s.prepaidUnits?.suspended ?? 0}`);
  }

  // 2. Per-user licence assignment (deduped by lower-cased UPN)
  const licensed = new Map();
  for (const s of copilotSkus) {
    const url =
      `${GRAPH}/users?$filter=assignedLicenses/any(x:x/skuId eq ${s.skuId})` +
      `&$select=userPrincipalName,displayName,department,accountEnabled&$count=true&$top=999`;
    const users = await graphGetAll(url, token, { ConsistencyLevel: 'eventual' });
    for (const u of users) {
      const upn = (u.userPrincipalName || '').toLowerCase();
      if (upn && !licensed.has(upn)) licensed.set(upn, { ...u, sku: s.skuPartNumber });
    }
  }

  for (const [upn, u] of licensed) {
    lines.push(
      `m365copilot.user_licensed,upn=${dim(upn)},user=${dim(u.displayName)},` +
      `department=${dim(u.department || 'Unassigned')},sku=${dim(u.sku)},` +
      `account_enabled=${dim(u.accountEnabled)} 1`
    );
  }

  // 3. Ingest via API token (chunked)
  const ingest = DRY_RUN ? { accepted: 0, invalid: [] } : await ingestMetrics(lines);

  return {
    dryRun: DRY_RUN,
    skus: copilotSkus.map((s) => ({
      sku: s.skuPartNumber,
      skuId: s.skuId,
      purchased: s.prepaidUnits?.enabled ?? 0,
      assigned: s.consumedUnits ?? 0,
    })),
    licensedUsers: licensed.size,
    disabledAccountsHoldingLicence: [...licensed.values()].filter((u) => u.accountEnabled === false).length,
    linesSent: DRY_RUN ? 0 : lines.length,
    linesAccepted: ingest.accepted,
    invalid: ingest.invalid,
    sample: lines.slice(0, 10),
  };
}
